/**
 * @brief FTRL(Follow-the-Regularized-Leader)算法实现
 * 
 * 实现了算法3-2中描述的FTRL在线学习算法
 */
class FTRL {
public:
    /**
     * @brief 构造函数，初始化FTRL算法参数
     * 
     * @param alpha 学习率参数
     * @param beta 学习率平滑参数，默认为1.0
     * @param lambda1 L1正则化强度
     * @param lambda2 L2正则化强度
     * @param n_features 特征维度，如果已知可以提前设置
     */
    FTRL(double alpha = 0.1, double beta = 1.0, double lambda1 = 1.0, double lambda2 = 1.0, size_t n_features = 0);

    /**
     * @brief 预测样本的概率
     * 
     * @param x 特征向量
     * @return double 预测概率
     */
    double predictProba(const std::vector<double>& x);

    /**
     * @brief 预测样本的类别
     * 
     * @param x 特征向量
     * @param threshold 分类阈值
     * @return int 类别预测结果，0或1
     */
    int predict(const std::vector<double>& x, double threshold = 0.5);

    /**
     * @brief 预测多个样本的概率
     * 
     * @param X 特征矩阵，每行是一个样本
     * @return std::vector<double> 预测概率数组
     */
    std::vector<double> predictProba(const std::vector<std::vector<double>>& X);

    /**
     * @brief 预测多个样本的类别
     * 
     * @param X 特征矩阵，每行是一个样本
     * @param threshold 分类阈值
     * @return std::vector<int> 类别预测结果数组
     */
    std::vector<int> predict(const std::vector<std::vector<double>>& X, double threshold = 0.5);

    /**
     * @brief 使用单个样本更新模型
     * 
     * @param x 特征向量
     * @param y 目标值
     * @return double 预测概率
     */
    double update(const std::vector<double>& x, double y);

    /**
     * @brief 训练FTRL模型
