#include "FTRL.h"

FTRL::FTRL(double alpha, double beta, double lambda1, double lambda2, size_t n_features)
    : alpha(alpha), beta(beta), lambda1(lambda1), lambda2(lambda2) {
    if (n_features > 0) {
        z.resize(n_features, 0.0);
        n.resize(n_features, 0.0);
        w.resize(n_features, 0.0);
    }
}

double FTRL::sigmoid(double x) {
    // 限制x值防止溢出
    x = std::max(-35.0, std::min(x, 35.0));
    return 1.0 / (1.0 + std::exp(-x));
}

double FTRL::sign(double x) {
    if (x > 0) return 1.0;
    if (x < 0) return -1.0;
    return 0.0;
}

void FTRL::updateWeights() {
    // 根据z和n更新权重w
    for (size_t i = 0; i < z.size(); ++i) {
        // 如果|z_i| <= lambda1，则w_i = 0
        if (std::abs(z[i]) <= lambda1) {
            w[i] = 0.0;
        } else {
            // 否则使用公式计算w_i
            double denominator = (beta + std::sqrt(n[i])) / alpha + lambda2;
            w[i] = -(z[i] - sign(z[i]) * lambda1) / denominator;
        }
    }
}

double FTRL::predictProba(const std::vector<double>& x) {
    // 如果模型未训练，初始化参数
    if (w.empty()) {
        size_t n_features = x.size();
        z.resize(n_features, 0.0);
        n.resize(n_features, 0.0);
        w.resize(n_features, 0.0);
    }

    // 计算特征向量与权重的点积
    double wx = 0.0;
    for (size_t i = 0; i < x.size() && i < w.size(); ++i) {
        wx += x[i] * w[i];
    }

    return sigmoid(wx);
}

int FTRL::predict(const std::vector<double>& x, double threshold) {
    return predictProba(x) >= threshold ? 1 : 0;
}

std::vector<double> FTRL::predictProba(const std::vector<std::vector<double>>& X) {
    std::vector<double> predictions;
    predictions.reserve(X.size());

    for (const auto& x : X) {
        predictions.push_back(predictProba(x));
    }

    return predictions;
}

std::vector<int> FTRL::predict(const std::vector<std::vector<double>>& X, double threshold) {
    std::vector<int> predictions;
    predictions.reserve(X.size());

    for (const auto& x : X) {
        predictions.push_back(predict(x, threshold));
    }

    return predictions;
}

double FTRL::update(const std::vector<double>& x, double y) {
    // 如果模型未训练，初始化参数
    if (w.empty()) {
        size_t n_features = x.size();
        z.resize(n_features, 0.0);
        n.resize(n_features, 0.0);
        w.resize(n_features, 0.0);
    }

    // 步骤(b)：计算预测值p_t
    double p = predictProba(x);

    // 步骤(c)：更新参数
    for (size_t i = 0; i < x.size() && i < w.size(); ++i) {
        if (x[i] != 0.0) {  // 只更新非零特征，以处理稀疏数据
            // 计算梯度g_i
            double g_i = (p - y) * x[i];

            // 计算σ_i
            double sigma_i = (1.0 / alpha) * (std::sqrt(n[i] + g_i * g_i) - std::sqrt(n[i]));

            // 更新z_i
            z[i] += g_i - sigma_i * w[i];

            // 更新n_i
            n[i] += g_i * g_i;
        }
    }

    // 更新权重w
    updateWeights();

    return p;
}

void FTRL::fit(const std::vector<std::vector<double>>& X, const std::vector<double>& y, int num_epochs, bool shuffle) {
    if (X.empty() || y.empty() || X.size() != y.size()) {
        std::cerr << "Error: Invalid input data for training" << std::endl;
        return;
    }

    size_t n_samples = X.size();
    size_t n_features = X[0].size();

    // 初始化参数
    if (w.empty()) {
        z.resize(n_features, 0.0);
        n.resize(n_features, 0.0);
        w.resize(n_features, 0.0);
    }

    // 用于随机打乱数据的索引
    std::vector<size_t> indices(n_samples);
    for (size_t i = 0; i < n_samples; ++i) {
        indices[i] = i;
    }

    // 训练多轮
    std::random_device rd;
    std::mt19937 g(rd());

    for (int epoch = 0; epoch < num_epochs; ++epoch) {
        if (shuffle) {
            std::shuffle(indices.begin(), indices.end(), g);
        }

        // 对每个样本进行训练
        for (size_t i = 0; i < n_samples; ++i) {
            size_t idx = shuffle ? indices[i] : i;
            update(X[idx], y[idx]);
        }
    }
}

double FTRL::logLoss(const std::vector<std::vector<double>>& X, const std::vector<double>& y) {
    if (X.empty() || y.empty() || X.size() != y.size()) {
        std::cerr << "Error: Invalid input data for evaluation" << std::endl;
        return -1.0;
    }

    double loss = 0.0;
    size_t n_samples = X.size();

    for (size_t i = 0; i < n_samples; ++i) {
        double p = predictProba(X[i]);
        // 防止log(0)
        p = std::max(std::numeric_limits<double>::min(), std::min(p, 1.0 - std::numeric_limits<double>::epsilon()));
        loss -= (y[i] * std::log(p) + (1.0 - y[i]) * std::log(1.0 - p));
    }

    return loss / n_samples;
}

const std::vector<double>& FTRL::getWeights() const {
    return w;
}
