#include "utils.h"

std::pair<std::vector<std::vector<double>>, std::vector<double>> makeClassification(
    size_t n_samples, 
    size_t n_features, 
    size_t n_informative, 
    unsigned int random_seed) {

    if (n_informative > n_features) {
        n_informative = n_features;
    }

    std::vector<std::vector<double>> X(n_samples, std::vector<double>(n_features, 0.0));
    std::vector<double> y(n_samples, 0.0);

    // 初始化随机数生成器
    std::mt19937 gen(random_seed);
    std::normal_distribution<double> normal_dist(0.0, 1.0);
    std::uniform_real_distribution<double> uniform_dist(0.0, 1.0);

    // 生成信息特征的方向向量
    std::vector<std::vector<double>> informative_directions(n_informative, std::vector<double>(n_features, 0.0));
    for (size_t i = 0; i < n_informative; ++i) {
        for (size_t j = 0; j < n_features; ++j) {
            informative_directions[i][j] = normal_dist(gen);
        }
    }

    // 生成数据点
    for (size_t i = 0; i < n_samples; ++i) {
        // 生成随机特征
        for (size_t j = 0; j < n_features; ++j) {
            X[i][j] = normal_dist(gen);
        }

        // 计算线性组合作为线性分类器
        double linear_comb = 0.0;
        for (size_t j = 0; j < n_informative; ++j) {
            for (size_t k = 0; k < n_features; ++k) {
                linear_comb += X[i][k] * informative_directions[j][k];
            }
        }

        // 按照sigmoid函数生成标签
        double prob = 1.0 / (1.0 + std::exp(-linear_comb));
        y[i] = uniform_dist(gen) < prob ? 1.0 : 0.0;
    }

    return {X, y};
}

// 辅助函数：计算AUC值
double rocAucScore(const std::vector<double>& y_true, const std::vector<double>& y_score) {
    if (y_true.size() != y_score.size() || y_true.empty()) {
        throw std::invalid_argument("Invalid input for AUC calculation");
    }

    // 统计正样本和负样本的数量
    size_t n_pos = 0;
    for (const auto& y : y_true) {
        if (y > 0.5) n_pos++;
    }
    size_t n_neg = y_true.size() - n_pos;

    if (n_pos == 0 || n_neg == 0) {
        throw std::invalid_argument("AUC requires both positive and negative samples");
    }

    // 创建(score, label)对并按score降序排序
    std::vector<std::pair<double, double>> score_label;
    for (size_t i = 0; i < y_true.size(); ++i) {
        score_label.push_back({y_score[i], y_true[i]});
    }

    std::sort(score_label.begin(), score_label.end(), 
              [](const auto& a, const auto& b) { return a.first > b.first; });

    // 计算AUC
    double rank_sum = 0.0;
    size_t rank = 0;

    for (const auto& pair : score_label) {
        rank++;
        if (pair.second > 0.5) {
            rank_sum += rank;
        }
    }

    // 计算并返回AUC
    return (rank_sum - n_pos * (n_pos + 1) / 2.0) / (n_pos * n_neg);
}

std::tuple<std::vector<std::vector<double>>, std::vector<std::vector<double>>, 
           std::vector<double>, std::vector<double>> 
trainTestSplit(const std::vector<std::vector<double>>& X, const std::vector<double>& y, 
               double test_size, unsigned int random_seed) {

    if (X.size() != y.size() || X.empty()) {
        throw std::invalid_argument("Invalid input for train_test_split");
    }

    size_t n_samples = X.size();
    size_t test_samples = static_cast<size_t>(std::round(n_samples * test_size));

    if (test_samples == 0) test_samples = 1;
    if (test_samples >= n_samples) test_samples = n_samples / 2;

    // 创建随机索引
    std::vector<size_t> indices(n_samples);
    for (size_t i = 0; i < n_samples; ++i) {
        indices[i] = i;
    }

    // 随机打乱索引
    std::mt19937 g(random_seed);
    std::shuffle(indices.begin(), indices.end(), g);

    // 分配训练集和测试集
    std::vector<std::vector<double>> X_train, X_test;
    std::vector<double> y_train, y_test;

    X_train.reserve(n_samples - test_samples);
    X_test.reserve(test_samples);
    y_train.reserve(n_samples - test_samples);
    y_test.reserve(test_samples);

    for (size_t i = 0; i < n_samples; ++i) {
        size_t idx = indices[i];
        if (i < test_samples) {
            X_test.push_back(X[idx]);
            y_test.push_back(y[idx]);
        } else {
            X_train.push_back(X[idx]);
            y_train.push_back(y[idx]);
        }
    }

    return {X_train, X_test, y_train, y_test};
}
