#include <iostream>
#include <iomanip>
#include "FTRL.h"
#include "utils.h"

/**
 * @brief 打印向量内容
 * 
 * @param vec 向量
 * @param n 显示的元素数量
 */
template<typename T>
void printVector(const std::vector<T>& vec, size_t n) {
    std::cout << "[";
    for (size_t i = 0; i < std::min(n, vec.size()); ++i) {
        std::cout << vec[i];
        if (i < std::min(n, vec.size()) - 1) {
            std::cout << ", ";
        }
    }
    std::cout << "]" << std::endl;
}

int main() {
    // 生成分类数据集
    std::cout << "生成数据集..." << std::endl;
    auto [X, y] = makeClassification(10000, 20, 10);

    // 划分训练集和测试集
    std::cout << "划分训练集和测试集..." << std::endl;
    auto [X_train, X_test, y_train, y_test] = trainTestSplit(X, y, 0.2);

    std::cout << "训练集样本数: " << X_train.size() << std::endl;
    std::cout << "测试集样本数: " << X_test.size() << std::endl;

    // 创建FTRL模型并训练
    std::cout << "训练FTRL模型..." << std::endl;
    FTRL ftrl(0.1, 1.0, 1.0, 1.0);
    ftrl.fit(X_train, y_train, 5, true);

    // 获取预测概率
    std::vector<double> y_train_pred = ftrl.predictProba(X_train);
    std::vector<double> y_test_pred = ftrl.predictProba(X_test);

    // 计算性能指标
    double train_log_loss = ftrl.logLoss(X_train, y_train);
    double test_log_loss = ftrl.logLoss(X_test, y_test);

    double train_auc = rocAucScore(y_train, y_train_pred);
    double test_auc = rocAucScore(y_test, y_test_pred);

    // 输出结果
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "训练集Log Loss: " << train_log_loss << std::endl;
    std::cout << "测试集Log Loss: " << test_log_loss << std::endl;
    std::cout << "训练集AUC: " << train_auc << std::endl;
    std::cout << "测试集AUC: " << test_auc << std::endl;

    // 输出前5个样本的预测结果
    std::cout << "\n前5个测试样本的预测概率: ";
    printVector(y_test_pred, 5);

    std::cout << "前5个测试样本的真实标签: ";
    printVector(y_test, 5);

    // 输出部分模型权重
    std::cout << "\n部分模型权重: ";
    printVector(ftrl.getWeights(), 10);

    return 0;
}
